import React, { useState } from "react";
import "./CreateProjectForm.css"; 
import HouseDetailsForm from "./HouseDetailsForm"; 

const CreateProjectForm = ({ onCreate }) => {
  const [builderName, setBuilderName] = useState("");
  const [customBuilderName, setCustomBuilderName] = useState("");
  const [location, setLocation] = useState("");
  const [budget, setBudget] = useState("");
  const [permit, setPermit] = useState("");
  const [startDate, setStartDate] = useState("");
  const [customStartDate, setCustomStartDate] = useState("");
  const [plotRegistered, setPlotRegistered] = useState("");
  const [floorArea, setFloorArea] = useState("");
  const [profession, setProfession] = useState("");
  const [customProfession, setCustomProfession] = useState("");
  const [showHouseDetails, setShowHouseDetails] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    const builder = builderName === "Other" ? customBuilderName : builderName;
    const start = startDate === "others" ? customStartDate : startDate;
    const prof = profession === "others" ? customProfession : profession;
    onCreate({
      builder,
      location,
      budget,
      permit,
      start,
      plotRegistered,
      floorArea,
      prof,
    });
    setShowHouseDetails(true);
  };

  return (
    <>
      {!showHouseDetails ? (
        <form onSubmit={handleSubmit} className="form-container">
          <h2 className="form-heading">Create a New Project</h2>

          <div className="form-group">
            <label htmlFor="builderName" className="form-label">Builder Name</label>
            <select
              id="builderName"
              className="form-select"
              value={builderName}
              onChange={(e) => setBuilderName(e.target.value)}
              required
            >
              <option value="" disabled>Select Builder</option>
              <option value="Om Prakash (Heights Co.)">Builder 1</option>
              <option value="Shrishti Deshmuk (Unchai Constructions)">Builder 2</option>
              <option value="Akash Shetty (Pune dream Home Construction)">Builder 3</option>
              <option value="Other">Other</option>
            </select>
            {builderName === "Other" && (
              <input
                type="text"
                className="form-control custom-input"
                placeholder="Enter builder name"
                value={customBuilderName}
                onChange={(e) => setCustomBuilderName(e.target.value)}
                required
              />
            )}
          </div>

          <div className="form-group">
            <label htmlFor="location" className="form-label">Location</label>
            <input
              type="text"
              id="location"
              className="form-control"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">What is your budget?</label>
            {["More than 2cr", "1cr to 2cr", "50L to 1cr", "20L to 50L", "Less than 20L"].map((label, index) => (
              <div key={index} className="form-check">
                <input
                  type="radio"
                  id={`budget${index + 1}`}
                  name="budget"
                  value={`level${index + 1}`}
                  className="form-check-input"
                  onChange={(e) => setBudget(e.target.value)}
                  required
                />
                <label htmlFor={`budget${index + 1}`} className="form-check-label">{label}</label>
              </div>
            ))}
          </div>

          <div className="form-group">
            <label className="form-label">Do you have government permit to construct?</label>
            {["Yes I have permit", "I have applied", "Yet To Apply", "Permit Not Required"].map((label, index) => (
              <div key={index} className="form-check">
                <input
                  type="radio"
                  id={`permit${index}`}
                  name="permit"
                  value={label}
                  className="form-check-input"
                  onChange={(e) => setPermit(e.target.value)}
                  required
                />
                <label htmlFor={`permit${index}`} className="form-check-label">{label}</label>
              </div>
            ))}
          </div>

          <div className="form-group">
            <label htmlFor="startDate" className="form-label">When do you want to start the construction?</label>
            <select
              id="startDate"
              className="form-select"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              required
            >
              <option value="" disabled>Select</option>
              <option value="immediately">Immediately</option>
              <option value="within 3 months">Within 3 months</option>
              <option value="within 6 months">Within 6 months</option>
              <option value="after 6 months">After 6 months</option>
              <option value="others">Others - specify date</option>
            </select>
            {startDate === "others" && (
              <input
                type="date"
                className="form-control custom-input"
                value={customStartDate}
                onChange={(e) => setCustomStartDate(e.target.value)}
                required
              />
            )}
          </div>

          <div className="form-group">
            <label className="form-label">Is the plot registered under your name?</label>
            {["Yes", "No"].map((label, index) => (
              <div key={index} className="form-check">
                <input
                  type="radio"
                  id={`plotRegistered${index}`}
                  name="plotRegistered"
                  value={label}
                  className="form-check-input"
                  onChange={(e) => setPlotRegistered(e.target.value)}
                  required
                />
                <label htmlFor={`plotRegistered${index}`} className="form-check-label">{label}</label>
              </div>
            ))}
          </div>

          <div className="form-group">
            <label htmlFor="floorArea" className="form-label">Floor Area (in sq. ft.)</label>
            <input
              type="text"
              id="floorArea"
              className="form-control"
              value={floorArea}
              onChange={(e) => setFloorArea(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="profession" className="form-label">Select your Profession</label>
            <select
              id="profession"
              className="form-select"
              value={profession}
              onChange={(e) => setProfession(e.target.value)}
              required
            >
              <option value="" disabled>Select Profession</option>
              <option value="Salaried">Salaried</option>
              <option value="Self Employed">Self Employed</option>
              <option value="Business Owner">Business Owner</option>
              <option value="Retired">Retired</option>
              <option value="Student">Student</option>
              <option value="Others">Others</option>
            </select>
            {profession === "Others" && (
              <input
                type="text"
                className="form-control custom-input"
                placeholder="Enter your profession"
                value={customProfession}
                onChange={(e) => setCustomProfession(e.target.value)}
                required
              />
            )}
          </div>

          <button type="submit" className="btn btn-primary submit-button">Submit</button>
        </form>
      ) : (
        <HouseDetailsForm />
      )}
    </>
  );
};

export default CreateProjectForm;
